#!/usr/bin/env node
// Generates every derived artefact from design/tokens.json: the ONE source for colour, type, space, radius, shadow
// and chrome sizing (plan docs/rewrite-plan.md §4.1). Never hand-edit the files this writes — edit tokens.json and
// run `node scripts/gen-tokens.mjs`. `--check` regenerates into memory and fails if any output file would change,
// which is the CI gate that keeps the generated files from drifting out of sync with the source (plan §9, "tokens
// diff").
//
// What this writes:
//   internal/web/static/design-tokens.css        the scale (radius/type/space/shadow/motion) — legacy UI reads it
//   android/.../ui/theme/GeneratedDimens.kt       space / radius / font size / chrome as Dp and Sp
//   android/.../ui/theme/GeneratedTokens.kt       colour ints per theme × mode, for Compose to read instead of
//                                                 hand-mirroring hex (this is what fixes the Tide colour drift)
//   docs/design-tokens.md                         a human-readable summary of the current values
//
// No dependencies beyond Node's stdlib on purpose: this must run in CI and in a plain `node` invocation alike.

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const tokensPath = path.join(root, "design/tokens.json");
const tokens = JSON.parse(readFileSync(tokensPath, "utf8"));

const CHECK = process.argv.includes("--check");

// ---------------------------------------------------------------------------------------------------------------
// internal/web/static/design-tokens.css — the scale only. Colours stay in theme-tokens.css (legacy, hand-written)
// until Phase 1 builds the full theme generator for the new app; regenerating the scale now is low-risk and proves
// the pipeline end to end before touching the more complex palette selectors.
// ---------------------------------------------------------------------------------------------------------------
function designTokensCSS() {
  const r = tokens.radius, f = tokens.fontSize, s = tokens.space, m = tokens.motion, e = tokens.elevation;
  const radius = Object.entries(r).map(([k, v]) => `--r-${k}:${v === 999 ? "999px" : v + "px"}`).join(";");
  const fontSize = Object.entries(f).map(([k, v]) => `--fs-${k}:${v}px`).join(";");
  const space = Object.entries(s).map(([k, v]) => `--sp-${k}:${v}px`).join(";");
  const shadows = Object.entries(e.steps)
    .map(([step, alpha]) => `  --shadow-${step}:0 ${{ "1": "2px 8px", "2": "9px 22px", "3": "14px 36px", "4": "20px 60px" }[step]} rgb(var(--elev-rgb)/calc(${alpha}*var(--elev-a)));`)
    .join("\n");
  return `/* GENERATED by scripts/gen-tokens.mjs from design/tokens.json. Do not hand-edit — edit tokens.json instead.
   One scale for radius, type, spacing, elevation and motion. Styles use these instead of one-off numbers, so a
   change here reaches every screen. Colours stay in the theme and palette blocks of app.css and theme-tokens.css. */
:root{
  ${radius};
  ${fontSize};
  ${space};
  --ease:${m.ease};--dur-fast:${m.durationFast};--dur:${m.duration};
  --elev-rgb:${e.dark.rgb};--elev-a:${e.dark.alpha};
${shadows}
}
:root[data-theme=light]{--elev-rgb:${e.light.rgb};--elev-a:${e.light.alpha}}
:root[data-palette=eink]{--shadow-1:none;--shadow-2:none;--shadow-3:none;--shadow-4:none}
@media (prefers-reduced-motion:reduce){:root{--dur-fast:0s;--dur:0s}}
`;
}

// ---------------------------------------------------------------------------------------------------------------
// web/src/styles/tokens.css — the full set for the new app: scale + chrome sizes + every theme's colours as CSS
// custom properties, selected by `[data-palette]`/`[data-theme]` attributes on the root element (same attribute
// names the legacy app already uses, so the theme switcher doesn't need new plumbing). Unlike the legacy
// `design-tokens.css` (scale only, colours stay hand-written in `theme-tokens.css`), this file is the single
// source end to end — Phase 1 has no legacy palette CSS to keep in sync with.
// ---------------------------------------------------------------------------------------------------------------
function webTokensCSS() {
  const r = tokens.radius, f = tokens.fontSize, s = tokens.space, m = tokens.motion, c = tokens.chrome, e = tokens.elevation;
  const radius = Object.entries(r).map(([k, v]) => `--radius-${k}:${v === 999 ? "999px" : v + "px"}`).join(";");
  const fontSize = Object.entries(f).map(([k, v]) => `--font-size-${k}:${v}px`).join(";");
  const space = Object.entries(s).map(([k, v]) => `--space-${k}:${v}px`).join(";");
  const kebab = (k) => k.replace(/[A-Z]/g, (ch) => "-" + ch.toLowerCase());
  const chrome = Object.entries(c)
    .filter(([k, v]) => k !== "note" && typeof v === "number")
    .map(([k, v]) => `--chrome-${kebab(k)}:${v}px`)
    .join(";");
  const shadowOffsets = { "1": "2px 8px", "2": "9px 22px", "3": "14px 36px", "4": "20px 60px" };
  const shadows = Object.entries(e.steps)
    .map(([step, alpha]) => `  --shadow-${step}:0 ${shadowOffsets[step]} rgb(var(--elev-rgb)/calc(${alpha}*var(--elev-a)));`)
    .join("\n");

  const paletteBlocks = tokens.canonicalThemes.map((id) => {
    const theme = tokens.themes[id];
    const colorVars = (mode) => roleOrder.map((role) => `--color-${kebab(role)}:${theme[mode][role]}`).join(";");
    // Dark is the default mode for a palette (matches the legacy default); [data-theme=light] overrides it.
    return `:root[data-palette="${id}"]{${colorVars("dark")}}\n:root[data-palette="${id}"][data-theme="light"]{${colorVars("light")}}`;
  }).join("\n");

  return `/* GENERATED by scripts/gen-tokens.mjs from design/tokens.json. Do not hand-edit — edit tokens.json instead.
   This is the ONE stylesheet with raw numbers or hex in the whole web/ app (plan docs/rewrite-plan.md §4.1, L3):
   every module elsewhere reads a var() from here. Palette selection mirrors the legacy app's own
   [data-palette]/[data-theme] attributes so the existing theme switcher UX needs no new plumbing. */
:root{
  ${radius};
  ${fontSize};
  ${space};
  ${chrome};
  --font-ui:${tokens.typeFamily.ui};--font-display:${tokens.typeFamily.display};
  --ease:${m.ease};--duration-fast:${m.durationFast};--duration:${m.duration};
  --elev-rgb:${e.dark.rgb};--elev-a:${e.dark.alpha};
${shadows}
}
:root[data-theme="light"]{--elev-rgb:${e.light.rgb};--elev-a:${e.light.alpha}}
${paletteBlocks}
:root[data-palette="eink"]{--shadow-1:none;--shadow-2:none;--shadow-3:none;--shadow-4:none}
@media (prefers-reduced-motion:reduce){:root{--duration-fast:0s;--duration:0s}}
`;
}

// ---------------------------------------------------------------------------------------------------------------
// android/.../ui/theme/GeneratedTokens.kt — one Kotlin object per theme, exposing a Color per mode per role. The
// existing Theme.kt calls these instead of literal hex, which is what stops phone/TV drifting from the web palette
// (the Tide colour drift found 21 Nov 2026: Compose Tide was #45DCD4/#334246, the web's is #38e0c6/#0b2b2c — two
// different colours under the same name, because nothing enforced they match).
// ---------------------------------------------------------------------------------------------------------------
const kotlinIdentifier = (id) => id.replace(/(^|-)([a-z])/g, (_, __, c) => c.toUpperCase());
// `warning` sits between error and success because that is what it is for: the middle of a scale — a match that is
// half right, a value that is not wrong but not settled. On e-ink it is the text colour like the other two, since a
// monochrome screen has no third hue to spend.
const roleOrder = ["bg", "surface", "raised", "line", "text", "muted", "accent", "accentInk", "wash", "error", "success", "warning", "accentVideo", "accentMusic", "accentPodcast", "accentComics"];

function generatedTokensKt() {
  const themeObjects = tokens.canonicalThemes.map((id) => {
    const name = kotlinIdentifier(id);
    const theme = tokens.themes[id];
    const modeBlock = (mode) => {
      const colors = theme[mode];
      const lines = roleOrder.map((role) => `            override val ${role}: Long = 0xFF${colors[role].replace("#", "").toUpperCase()}`).join("\n");
      return `        object ${mode === "dark" ? "Dark" : "Light"} : Mode {\n${lines}\n        }`;
    };
    return `    /** ${theme.label} — ${theme.description} */\n    object ${name} {\n${modeBlock("dark")}\n\n${modeBlock("light")}\n    }`;
  }).join("\n\n");

  const roleDecls = roleOrder.map((role) => `        val ${role}: Long`).join("\n");

  return `// GENERATED by scripts/gen-tokens.mjs from design/tokens.json. Do not hand-edit — edit tokens.json instead.
//
// One colour value per theme per mode per role, read by Theme.kt instead of literal hex, so the phone and TV themes
// cannot silently drift from the web palette the way Tide once did (Compose had #45DCD4/#334246 while the web's
// Tide/kiln was #38e0c6/#0b2b2c — found and fixed 21 Nov 2026).
package net.kdhmedia.mochil.ui.theme

object GeneratedTokens {
    /** One mode (Dark or Light) of one theme, so Theme.kt can read either without knowing which theme it came from. */
    interface Mode {
${roleDecls}
    }

${themeObjects}
}
`;
}

// ---------------------------------------------------------------------------------------------------------------
// android/.../ui/theme/GeneratedDimens.kt — the sizes, not the colours: spacing, radius, type size and chrome height as
// Compose Dp/Sp, so a phone screen reads `MochilSpace.s16` instead of a literal `16.dp` and cannot drift from the web
// the way a hand-copied number does. Keys that are plain numbers become `s<N>` (space, font size) or `r<N>` (radius).
// ---------------------------------------------------------------------------------------------------------------
function generatedDimensKt() {
  const num = (n) => `${n}`;
  const scale = (name, doc, entries, prefix, unit) => {
    const lines = Object.entries(entries).map(([key, value]) => {
      const id = /^\d+$/.test(key) ? `${prefix}${key}` : key;
      return `    val ${id}: ${unit === "sp" ? "TextUnit" : "Dp"} = ${num(value)}.${unit}`;
    });
    return `/** ${doc} */\nobject ${name} {\n${lines.join("\n")}\n}`;
  };
  const chromeEntries = Object.entries(tokens.chrome).filter(([, value]) => typeof value === "number");
  const chrome = chromeEntries.map(([key, value]) => `    val ${key}: Dp = ${num(value)}.dp`).join("\n");
  return `// GENERATED by scripts/gen-tokens.mjs from design/tokens.json. Do not hand-edit — edit tokens.json instead.
//
// The web's spacing, radius, type-size and chrome tokens as Compose units. A screen reads MochilSpace.s16 rather than a
// literal 16.dp, so the phone and the web move together when a token changes.
package net.kdhmedia.mochil.ui.theme

import androidx.compose.ui.unit.Dp
import androidx.compose.ui.unit.TextUnit
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp

${scale("MochilSpace", "tokens.space — 4/8/12/16/24/32/48.", tokens.space, "s", "dp")}

${scale("MochilRadius", "tokens.radius — \`pill\` is the fully rounded end.", tokens.radius, "r", "dp")}

${scale("MochilFontSize", "tokens.fontSize — the web's px as sp (11 is 11.5, 12 is 12.5).", tokens.fontSize, "s", "sp")}

/** tokens.chrome — heights and widths of the shell itself. */
object MochilChrome {
${chrome}
}
`;
}

// ---------------------------------------------------------------------------------------------------------------
// docs/design-tokens.md — human-readable, so a person can check a value without reading JSON or Kotlin.
// ---------------------------------------------------------------------------------------------------------------
function designTokensMd() {
  const themeRows = tokens.canonicalThemes.map((id) => {
    const theme = tokens.themes[id];
    const swatch = (mode) => Object.entries(theme[mode]).map(([role, hex]) => `${role}=${hex}`).join(", ");
    return `### ${theme.label} (\`${id}\`)\n\n${theme.description}\n\n- **Dark:** ${swatch("dark")}\n- **Light:** ${swatch("light")}\n`;
  }).join("\n");
  const legacy = Object.entries(tokens.legacyPaletteMap).filter(([k]) => k !== "note")
    .map(([old, canonical]) => `- \`${old}\` → \`${canonical}\``).join("\n");
  return `# Design tokens — generated reference

GENERATED by \`scripts/gen-tokens.mjs\` from \`design/tokens.json\`. Do not hand-edit — edit tokens.json instead.
Reference theme: **${tokens.meta.reference_theme}** (every other theme matches its style with its own colours).

## Scale

- **Radius:** ${Object.entries(tokens.radius).map(([k, v]) => `${k}=${v}`).join(", ")}
- **Font size:** ${Object.entries(tokens.fontSize).map(([k, v]) => `${k}=${v}px`).join(", ")}
- **Space:** ${Object.entries(tokens.space).map(([k, v]) => `${k}px`).join(", ")}
- **Chrome:** header ${tokens.chrome.headerHeightDesktop}px desktop / ${tokens.chrome.headerHeightPhone}px phone, dock
  ${tokens.chrome.dockHeight}px / ${tokens.chrome.dockHeightPhone}px phone, sidebar ${tokens.chrome.sidebarWidth}px,
  mini player ${tokens.chrome.playerMiniHeight}px, touch target min ${tokens.chrome.touchMin}px

## Themes

${themeRows}

## Legacy palette migration

Old saved palette ids still read from storage migrate to one of the four canonical themes; anything unrecognised
lands on \`mochil\`.

${legacy}
`;
}

// ---------------------------------------------------------------------------------------------------------------
// web/src/lib/tokenMeta.ts — the small bits of tokens.json a React component needs at runtime (theme ids, the
// font-size scale's keys) without importing design/tokens.json across the web/ project root, which Vite's dev
// server refuses by default. Generated so the gallery can never list a theme or size that doesn't exist.
// ---------------------------------------------------------------------------------------------------------------
function tokenMetaTS() {
  const themeList = tokens.canonicalThemes.map((id) => JSON.stringify(id)).join(", ");
  const themeLabels = tokens.canonicalThemes
    .map((id) => `  ${JSON.stringify(id)}: ${JSON.stringify(tokens.themes[id].label)}`)
    .join(",\n");
  const fontSizeKeys = Object.keys(tokens.fontSize).map((k) => JSON.stringify(k)).join(", ");
  const spaceKeys = Object.keys(tokens.space).join(", ");
  const radiusKeys = Object.keys(tokens.radius).map((k) => JSON.stringify(k)).join(", ");
  // The theme a first-time visitor lands on. Taken from tokens.json's meta.reference_theme rather than being
  // canonicalThemes[0]: the array order is the order a switcher lists themes in, which is a presentation
  // choice, while "which one is the product" is a design decision — Kevin picked Tide, and it happens to be
  // listed second.
  const defaultTheme = JSON.stringify(tokens.meta.reference_theme);
  return `// GENERATED by scripts/gen-tokens.mjs from design/tokens.json. Do not hand-edit — edit tokens.json instead.
export const canonicalThemes = [${themeList}] as const;
export type CanonicalTheme = (typeof canonicalThemes)[number];
// The theme the app opens in (tokens.json meta.reference_theme). Not canonicalThemes[0] — that's list order.
export const defaultTheme = ${defaultTheme} as CanonicalTheme;
// The human-facing name for each theme (e.g. "kiln" reads as "Deep Teal (Tide)") — a theme switcher shows this,
// never the raw id, so a legacy name like "Tide" stays recognisable even though it's stored as an alias of kiln.
export const themeLabels: Record<CanonicalTheme, string> = {
${themeLabels},
};
export const fontSizeKeys = [${fontSizeKeys}] as const;
export type FontSizeKey = (typeof fontSizeKeys)[number];
export const spaceKeys = [${spaceKeys}] as const;
export type SpaceKey = (typeof spaceKeys)[number];
export const radiusKeys = [${radiusKeys}] as const;
export type RadiusKey = (typeof radiusKeys)[number];
`;
}

// ---------------------------------------------------------------------------------------------------------------
const outputs = [
  { path: "internal/web/static/design-tokens.css", content: designTokensCSS() },
  { path: "web/src/styles/tokens.css", content: webTokensCSS() },
  { path: "web/src/lib/tokenMeta.ts", content: tokenMetaTS() },
  { path: "android/app/src/main/java/net/kdhmedia/mochil/ui/theme/GeneratedTokens.kt", content: generatedTokensKt() },
  { path: "android/app/src/main/java/net/kdhmedia/mochil/ui/theme/GeneratedDimens.kt", content: generatedDimensKt() },
  { path: "docs/design-tokens.md", content: designTokensMd() },
];

let drift = false;
for (const { path: relPath, content } of outputs) {
  const abs = path.join(root, relPath);
  const current = existsSync(abs) ? readFileSync(abs, "utf8") : null;
  if (current === content) {
    console.log(`unchanged  ${relPath}`);
    continue;
  }
  if (CHECK) {
    drift = true;
    console.error(`DRIFT      ${relPath} does not match tokens.json — run: node scripts/gen-tokens.mjs`);
    continue;
  }
  writeFileSync(abs, content, "utf8");
  console.log(`${current === null ? "created  " : "updated  "}${relPath}`);
}

if (CHECK && drift) {
  console.error("\nGenerated files are out of sync with design/tokens.json.");
  process.exit(1);
}
